# Validates BUILD.txt generated by windows-binary.yml.
# GitHub pull_request jobs may build refs/pull/N/merge, not the source PR HEAD.
# Source PR identity is independently corroborated with gh run view headSha.
param(
    [Parameter(Mandatory = $true)][string]$BuildPath,
    [Parameter(Mandatory = $true)][string]$ExpectedSourceSha
)

$ErrorActionPreference = 'Stop'
if ($ExpectedSourceSha -notmatch '^[0-9a-fA-F]{40}$') {
    throw 'ExpectedSourceSha muss eine vollstaendige 40-stellige Git-SHA sein'
}
if (-not (Test-Path -LiteralPath $BuildPath -PathType Leaf)) {
    throw "BUILD.txt fehlt: $BuildPath"
}
$lines = @(Get-Content -LiteralPath $BuildPath)
if ($lines.Count -ne 2) {
    throw 'BUILD.txt muss genau zwei Commit-Identitaetszeilen enthalten'
}
if ($lines[0] -notmatch '^Commit:[ \t]*([0-9a-fA-F]{40})[ \t]*$') {
    throw 'BUILD.txt enthaelt keine gueltige vollstaendige Checkout-Commit-SHA'
}
$checkoutSha = $Matches[1]
if ($lines[1] -notmatch '^Source PR head commit:[ \t]*([0-9a-fA-F]{40})[ \t]*$') {
    throw 'BUILD.txt enthaelt keine gueltige vollstaendige Source-Commit-SHA'
}
$sourceSha = $Matches[1]
if ($sourceSha -ne $ExpectedSourceSha) {
    throw "BUILD.txt Source-SHA stimmt nicht mit dem erwarteten PR-HEAD ueberein"
}

[pscustomobject]@{
    checkout_commit = $checkoutSha
    source_head_commit = $sourceSha
    pull_request_merge_checkout = ($checkoutSha -ne $sourceSha)
}
